package run.ikaros.music;
import static org.mockito.ArgumentMatchers.any; import static org.mockito.Mockito.when; import java.time.Instant; import java.util.List; import java.util.UUID; import org.junit.jupiter.api.Test; import org.springframework.transaction.reactive.TransactionalOperator; import reactor.core.publisher.Mono; import reactor.test.StepVerifier; import run.ikaros.resource.api.ResourceLifecycle; import run.ikaros.resource.api.ResourceService; import run.ikaros.resource.api.ResourceType; import run.ikaros.resource.api.ResourceView;
class PersistentMusicTrackAssociationServiceTest {
    @Test void associatesCandidateWithIndependentArtistAlbumEdition() { UUID owner=UUID.randomUUID(),trackId=UUID.randomUUID(),candidateId=UUID.randomUUID(),trackResource=UUID.randomUUID(),artistResourceId=UUID.randomUUID(),albumResourceId=UUID.randomUUID(),artistId=UUID.randomUUID(),albumId=UUID.randomUUID(),editionId=UUID.randomUUID(),discId=UUID.randomUUID(),membershipId=UUID.randomUUID(),associationId=UUID.randomUUID(); MusicTrackRepository tracks=org.mockito.Mockito.mock(MusicTrackRepository.class); MusicMetadataCandidateRepository candidates=org.mockito.Mockito.mock(MusicMetadataCandidateRepository.class); MusicTrackAssociationRepository associations=org.mockito.Mockito.mock(MusicTrackAssociationRepository.class); MusicTrackArtistRepository trackArtists=org.mockito.Mockito.mock(MusicTrackArtistRepository.class); MusicArtistRepository artists=org.mockito.Mockito.mock(MusicArtistRepository.class); MusicAlbumRepository albums=org.mockito.Mockito.mock(MusicAlbumRepository.class); MusicEditionRepository editions=org.mockito.Mockito.mock(MusicEditionRepository.class); MusicDiscRepository discs=org.mockito.Mockito.mock(MusicDiscRepository.class); MusicTrackMembershipRepository memberships=org.mockito.Mockito.mock(MusicTrackMembershipRepository.class); ResourceService resources=org.mockito.Mockito.mock(ResourceService.class); TransactionalOperator transaction=org.mockito.Mockito.mock(TransactionalOperator.class); MusicTrackEntity track=new MusicTrackEntity(trackId,owner,trackResource,"song",null,null,false,0L); MusicMetadataCandidateEntity candidate=new MusicMetadataCandidateEntity(candidateId,owner,trackId,UUID.randomUUID(),"Song","Artist","Album",null,null,null,2,1,"2024","ID3",Instant.now(),Instant.now(),0L); when(tracks.findById(trackId)).thenReturn(Mono.just(track)); when(candidates.findById(candidateId)).thenReturn(Mono.just(candidate)); when(associations.findByOwnerIdAndTrackIdAndCandidateId(owner,trackId,candidateId)).thenReturn(Mono.empty()); when(resources.create(any(),any())).thenReturn(Mono.just(resource(artistResourceId)),Mono.just(resource(albumResourceId))); when(artists.save(any())).thenReturn(Mono.just(new MusicArtistEntity(artistId,owner,artistResourceId,"PRIMARY","Artist",null,0L))); when(albums.save(any())).thenReturn(Mono.just(new MusicAlbumEntity(albumId,owner,albumResourceId,"ALBUM",null,0L))); when(editions.save(any())).thenReturn(Mono.just(new MusicEditionEntity(editionId,owner,albumId,"Embedded metadata",null,null,null,null,null,0L))); when(discs.save(any())).thenReturn(Mono.just(new MusicDiscEntity(discId,editionId,1,null,"DIGITAL",1))); when(memberships.save(any())).thenReturn(Mono.just(new MusicTrackMembershipEntity(membershipId,editionId,discId,trackId,2,1,"Song",null,false))); when(trackArtists.save(any())).thenReturn(Mono.just(new MusicTrackArtistEntity(UUID.randomUUID(),owner,trackId,artistId,"PRIMARY",0))); when(associations.save(any())).thenReturn(Mono.just(new MusicTrackAssociationEntity(associationId,owner,trackId,candidateId,artistId,albumId,editionId,discId,membershipId,Instant.now(),0L))); when(transaction.transactional(any(Mono.class))).thenAnswer(i->i.getArgument(0));
        StepVerifier.create(new PersistentMusicTrackAssociationService(tracks,candidates,associations,trackArtists,artists,albums,editions,discs,memberships,resources,transaction).create(owner,trackId,new CreateMusicTrackAssociationRequest(candidateId))).expectNextMatches(v->v.artistId().equals(artistId)&&v.albumId().equals(albumId)&&v.trackNumber()==2).verifyComplete();
    }
    private ResourceView resource(UUID id){return new ResourceView(id,ResourceType.MUSIC,ResourceLifecycle.ACTIVE,List.of(),List.of(),Instant.now(),Instant.now());}
}
